document.addEventListener("DOMContentLoaded",function(){var menuToggle=document.querySelector(".header-menu__toggle.mobile");var mobileMenu=document.querySelector(".header__menu.header-menu.mobile");menuToggle.addEventListener("click",function(){menuToggle.classList.toggle("active");mobileMenu.classList.toggle("active")});var lazyBgItems=document.querySelectorAll("[data-bg]");function loadBgImages(){lazyBgItems.forEach(function(item){var bg=item.getAttribute("data-bg");item.style.backgroundImage="url("+bg+")"})}if("IntersectionObserver"in window){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){var item=entry.target;var bg=item.getAttribute("data-bg");item.style.backgroundImage="url("+bg+")";observer.unobserve(item)}})});lazyBgItems.forEach(function(item){observer.observe(item)})}else{loadBgImages()}var lazyImages=document.querySelectorAll("img[data-src]");function loadImage(image){var src=image.getAttribute("data-src");if(src){image.src=src}}if("IntersectionObserver"in window){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){var image=entry.target;loadImage(image);observer.unobserve(image)}})});lazyImages.forEach(function(image){observer.observe(image)})}else{lazyImages.forEach(function(image){loadImage(image)})}});